/**
 * UUIDv7: an identifier generated by the client (to create records offline)
 * that sorts by creation time.
 *
 * In React Native a polyfill is required before the first call:
 *   import 'react-native-get-random-values';
 *
 * The order of records created within the same millisecond is not guaranteed.
 */

function getRandomBytes(length: number): Uint8Array {
  const cryptoApi = (globalThis as { crypto?: { getRandomValues?: (a: Uint8Array) => Uint8Array } })
    .crypto;
  if (!cryptoApi?.getRandomValues) {
    throw new Error(
      'crypto.getRandomValues is unavailable. In React Native, import react-native-get-random-values.',
    );
  }
  return cryptoApi.getRandomValues(new Uint8Array(length));
}

const HEX = Array.from({ length: 256 }, (_, i) => i.toString(16).padStart(2, '0'));

export function uuidv7(nowMs: number = Date.now(), random?: Uint8Array): string {
  const bytes = new Uint8Array(16);
  bytes.set((random ?? getRandomBytes(16)).subarray(0, 16));

  // 48 bits of time (ms since epoch), most significant bytes first.
  for (let i = 0; i < 6; i++) {
    bytes[i] = Math.floor(nowMs / 2 ** (8 * (5 - i))) % 256;
  }

  bytes[6] = ((bytes[6] ?? 0) & 0x0f) | 0x70; // version 7
  bytes[8] = ((bytes[8] ?? 0) & 0x3f) | 0x80; // RFC 4122 variant

  const h = Array.from(bytes, (b) => HEX[b] as string);
  return `${h.slice(0, 4).join('')}-${h.slice(4, 6).join('')}-${h.slice(6, 8).join('')}-${h
    .slice(8, 10)
    .join('')}-${h.slice(10, 16).join('')}`;
}

/** Creation time in ms, encoded in the UUIDv7. */
export function uuidv7Timestamp(id: string): number {
  const hex = id.replace(/-/g, '').slice(0, 12);
  return parseInt(hex, 16);
}

export function isUuidv7(id: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id);
}
